    public static void main(String[] args) {
        // Get the root directory
        FileObject root = VFS.getManager().getRoot();

        // Iterate over all files and folders
        for (FileObject file : root.getContents()) {
            // Check if the file is a folder
            if (file.getType().equals(FileObject.TYPE_FOLDER)) {
                System.out.println(file.getName() + " is a folder");
            }
        }
    }
}
```

