import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

public class Main {
    public static Element getSiblingElement(Element parent, String name) {
        NodeList siblings = parent.getChildNodes();
        for (int i = 0; i < siblings.getLength(); i++) {
            if (siblings.item(i) instanceof Element && ((Element) siblings.item(i)).getTagName().equals(name)) {
                return (Element) siblings.item(i);
            }
        }
        return null;
    }

    public static void main(String[] args) {
        // Example usage:
        // Create a sample XML document
        String xml = "<root><person><name>John</name><age>30</age></person><person><name>Jane</name><age>25</age></person></root>";

        // Parse the XML document
        org.w3c.dom.Document doc = org.w3c.dom.DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(new java.io.ByteArrayInputStream(xml.getBytes()));

        // Get the root element
        Element root = doc.getDocumentElement();

        // Get the sibling element with the name "name"
        Element sibling = getSiblingElement(root, "name");

        if (sibling != null) {
            System.out.println("Found sibling element with name 'name': " + sibling.getTextContent());
        } else {
            System.out.println("No sibling element with name 'name' found.");
        }
    }
}
```

