        sourceStyle.setAlignment(XSSFAlignment.CENTER);

        XSSFCellStyle clonedStyle = cloneXSSFCellStyle(sourceStyle);
        // Now you can edit the cloned style independently
        clonedStyle.setFont(XSSFFontFactory.getInstance().createFont().setItalic(true));

        // Create a new style from scratch
        XSSFCellStyle newStyle = createNewXSSFCellStyle(workbook);
        newStyle.setFont(XSSFFontFactory.getInstance().createFont().setBold(true));
        newStyle.setAlignment(XSSFAlignment.CENTER);

