```java
public class CurveIntersection {
    public static boolean doIntersect(double[] quadCurve, double[] cubicCurve) {
        // Calculate the coefficients of the quadratic equation
        double a = quadCurve[0] * cubicCurve[0] + quadCurve[1] * cubicCurve[1] + quadCurve[2] * cubicCurve[2];
        double b = quadCurve[0] * cubicCurve[1] + quadCurve[1] * cubicCurve[0] + quadCurve[2] * cubicCurve[3];
        double c = quadCurve[0] * cubicCurve[2] + quadCurve[1] * cubicCurve[3] + quadCurve[2] * cubicCurve[0];
        double d = quadCurve[0] * cubicCurve[4] + quadCurve[1] * cubicCurve[5] + quadCurve[2] * cubicCurve[6];

        // Calculate the coefficients of the cubic equation
        double e = cubicCurve[0] * cubicCurve[1] * cubicCurve[2] + cubicCurve[1] * cubicCurve[2] * cubicCurve[3] + cubicCurve[2] * cubicCurve[3] * cubicCurve[4];
        double f = cubicCurve[0] * cubicCurve[1] * cubicCurve[5] + cubicCurve[1] * cubicCurve[2] * cubicCurve[6] + cubicCurve[2] * cubicCurve[3] * cubicCurve[7];
        double g = cubicCurve[0] * cubicCurve[3] * cubicCurve[4] + cubicCurve[1] * cubicCurve[3] * cubicCurve[7] + cubicCurve[2] * cubicCurve[4] * cubicCurve[6];
        double h = cubicCurve[0] * cubicCurve[5] * cubicCurve[4] + cubicCurve[1] * cubicCurve[6] * cubicCurve[3] + cubicCurve[2] * cubicCurve[7] * cubicCurve[2];

        // Calculate the discriminant of the cubic equation
        double discriminant = e * f * g - f * f * h + g * g * h - g * f * f * h + e * e * h - e * f * f * h;

