Here's a Java class that provides a helper method to turn on indentation for a XML Transformer that works correctly for both Saxon and Xalan.

```java
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.stream.StreamResult;
import javax.xml.transform.stream.StreamSource;
import java.io.StringWriter;
import java.io.IOException;

public class XmlTransformerHelper {

    public static String transformXml(String xmlString, String namespaceUri, String localName, boolean indent) throws Exception {
        // Create a TransformerFactory
        TransformerFactory factory = TransformerFactory.newInstance();

        // Create a Transformer
        Transformer transformer = factory.newTransformer();

        // Set the output property to indent if required
        if (indent) {
            transformer.setOutputProperty("{http://xml.apache.org/xslt}indent-amount", "4");
            transformer.setOutputProperty("{http://xml.apache.org/xslt}indent-yes", "yes");
        }

        // Create a StringWriter to hold the result
        StringWriter writer = new StringWriter();

        // Transform the XML string
        transformer.transform(new StreamSource(new StreamSource(new StringReader(xmlString))), new StreamResult(writer));

        // Return the transformed XML string
        return writer.toString();
    }

    public static void main(String[] args) throws Exception {
        String xmlString = "<root><person><name>John</name><age>30</age></person></root>";
        String namespaceUri = "http://example.com";
        String localName = "foo";
        boolean indent = true;

        String transformedXml = transformXml(xmlString, namespaceUri, localName, indent);
        System.out.println(transformedXml);
    }
}
