import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;

public class HmacSha1Generator {
    public static String generateHmacSha1Signature(String data, String key) throws NoSuchAlgorithmException, InvalidKeyException {
        // Create a new Mac object that implements the HMAC-SHA1 algorithm
        Mac mac = Mac.getInstance("HmacSHA1");

        // Create a new SecretKeySpec object that wraps the key
        SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8), "HmacSHA1");

        // Initialize the Mac object with the secret key
        mac.init(secretKeySpec);

        // Update the Mac object with the data to be signed
        mac.update(data.getBytes(StandardCharsets.UTF_8));

        // Get the HMAC-SHA1 signature
        byte[] signature = mac.doFinal();

        // Convert the signature to a hexadecimal string
        StringBuilder sb = new StringBuilder();
        for (byte b : signature) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

