```java
public String reverseComplement(String dna) {
    // Create a dictionary to map DNA bases to their complements
    String[] baseComplement = {"A", "T", "C", "G"};
    String[] baseComplementMap = {"T", "A", "G", "C"};

    // Initialize an empty string to store the reverse complement
    StringBuilder reverseComplement = new StringBuilder();

    // Iterate over the DNA string from right to left
    for (int i = dna.length() - 1; i >= 0; i--) {
        // Get the current base
        char base = dna.charAt(i);

        // Check if the base is valid
        if (!baseComplementMap.contains(base)) {
            throw new IllegalArgumentException("Invalid DNA base: " + base);
        }

        // Append the complement of the base to the reverse complement
        reverseComplement.append(baseComplementMap[baseComplement.indexOf(base)]);
    }

    // Return the reverse complement in upper case
    return reverseComplement.toString().toUpperCase();
}
```

