```java
public class GaussianBlurFilter {

    private double sigma;
    private int kernelSize;

    public GaussianBlurFilter(double sigma, int kernelSize) {
        this.sigma = sigma;
        this.kernelSize = kernelSize;
    }

    public double[] apply(double[] image) {
        double[] kernel = createKernel();
        double[] blurredImage = new double[image.length];

        for (int i = 0; i < image.length; i++) {
            double sum = 0;
            for (int j = 0; j < kernelSize; j++) {
                int index = i - (kernelSize / 2) + j;
                if (index >= 0 && index < image.length) {
                    sum += image[index] * kernel[j];
                }
            }
            blurredImage[i] = sum;
        }

        return blurredImage;
    }

    private double[] createKernel() {
        double[] kernel = new double[kernelSize];
        double sigmaSquared = Math.sqrt(sigma * sigma);

        for (int i = 0; i < kernelSize; i++) {
            double x = (i - kernelSize / 2) / sigma;
            kernel[i] = Math.exp(-x * x / 2) / (2 * Math.PI * sigmaSquared);
        }

        return kernel;
    }
}
```

