import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;

public class DefaultMonochromeBitmapConverter {

    public static BufferedImage convertToMonochromeBitmap(String filePath) throws IOException {
        // Load the image from the file
        BufferedImage image = ImageIO.read(new File(filePath));

        // Create a new monochrome BufferedImage with the same dimensions as the original image
        BufferedImage monochromeImage = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_BYTE_GRAY);

        // Get the Graphics2D context for the monochrome image
        Graphics2D graphics = monochromeImage.createGraphics();

        // Set the color of the graphics context to black
        graphics.setColor(Color.BLACK);

        // Draw the original image onto the monochrome image
        graphics.drawImage(image, 0, 0, null);

        // Dispose of the graphics context
        graphics.dispose();

        // Return the monochrome image
        return monochromeImage;
    }

    public static void main(String[] args) throws IOException {
        BufferedImage monochromeImage = convertToMonochromeBitmap("path_to_your_image.jpg");
        // Save the monochrome image to a file
        ImageIO.write(monochromeImage, "jpg", new File("monochrome_image.jpg"));
    }
}
```

