```java
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        String str = "Hello World";
        StringTokenizer st = new StringTokenizer(str, " ");
        StringBuilder reversedStr = new StringBuilder();

        while (st.hasMoreTokens()) {
