Here's an example of how you can list the name and class of objects in a Java Naming Context (JNDI) using the provided API methods:

```java
import javax.naming.Context;
import javax.naming.NamingEnumeration;
import javax.naming.NamingException;
import javax.naming.directory.Attribute;
import javax.naming.directory.Attributes;
import javax.naming.directory.DirContext;
import javax.naming.directory.InitialDirContext;
import javax.naming.directory.SearchControls;
import javax.naming.directory.SearchResult;

public class JNDIList {

    public static void main(String[] args) throws NamingException {
        // Create a context
        DirContext context = new InitialDirContext(
                new java.util.Hashtable<String, String>() {{
                    put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.cosnaming.COSNamingContextFactory");
                    put(Context.PROVIDER_URL, "localhost:10035");
                }}
        );

        // Create a search controls object
        SearchControls controls = new SearchControls();
        controls.setSearchScope(SearchControls.SUBTREE_SCOPE);

        // Perform a search
        NamingEnumeration<SearchResult> results = context.search("java:comp/env", null, controls);

        // List the name and class of objects
        while (results.hasMore()) {
            SearchResult result = results.next();
            Attributes attributes = result.getAttributes();
            for (Attribute attribute : attributes.getAttributes()) {
                System.out.println("Name: " + attribute.getSingleValue() + ", Class: " + attribute.getSingleValue().getClass().getName());
            }
        }

        // Close the context
        context.close();
    }
}
```

Here's an explanation of each API method:

