Here's how you can get the MAC address of a host in Java using the provided API methods:

```java
import java.net.InetAddress;
import java.net.NetworkInterface;
import java.net.SocketException;
import java.net.UnknownHostException;

public class Main {

    public static void main(String[] args) throws UnknownHostException, SocketException {
        // Get the MAC address of the host
        String macAddress = getMacAddress();
        System.out.println("MAC Address: " + macAddress);
    }

    public static String getMacAddress() throws UnknownHostException, SocketException {
        // Get the network interface
        NetworkInterface networkInterface = NetworkInterface.getByInetAddress(InetAddress.getLoopbackAddress());

        // Get the hardware address (MAC address) of the interface
        byte[] hardwareAddress = networkInterface.getHardwareAddress();

        // Convert the hardware address to a string
        StringBuilder sb = new StringBuilder();
        for (byte b : hardwareAddress) {
            sb.append(String.format("%02X:", b));
        }
        if (sb.length() > 0) {
            sb.deleteCharAt(sb.length() - 1);
        }
        return sb.toString();
    }
}
```

