```java
import java.awt.ColorSpace;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;

public class Main {
    public static void main(String[] args) {
        // Create a new image
        BufferedImage img = new BufferedImage(800, 600, BufferedImage.TYPE_INT_RGB);

        // Draw something on the image
        for (int y = 0; y < img.getHeight(); y++) {
            for (int x = 0; x < img.getWidth(); x++) {
                int color = new Color(x, y).getRGB();
                img.setRGB(x, y, color);
            }
        }

        // Convert the image to grayscale
        convertToGrayscale(img);

        // Display the grayscale image
        img.show();
    }

    public static void convertToGrayscale(BufferedImage img) {
        // Get the pixel data
        DataBufferInt data = (DataBufferInt) img.getRaster().getDataBuffer();
        int[] pixels = ((IntBuffer) data.getData().getArray()).array();

        // Iterate over each pixel
        for (int i = 0; i < pixels.length; i += 4) {
            // Get the RGB values of the pixel
            int r = pixels[i];
            int g = pixels[i + 1];
            int b = pixels[i + 2];

            // Calculate the grayscale value
            int gray = (int) (0.2126 * r + 0.7152 * g + 0.0722 * b);

            // Set the grayscale value
            pixels[i] = gray;
            pixels[i + 1] = gray;
            pixels[i + 2] = gray;
        }

        // Set the pixel data back
        data.data.setArray((IntBuffer) data.getData().getArray(), pixels);
    }
}
```

