```java
public class CorrelationCalculator {

    /**
     * Calculates the correlation between two arrays of data.
     * 
     * @param array1 The first array of data.
     * @param array2 The second array of data.
     * @return The correlation between the two arrays.
     */
    public static double calculateCorrelation(double[] array1, double[] array2) {
        // Calculate the means of the two arrays
        double mean1 = calculateMean(array1);
        double mean2 = calculateMean(array2);

        // Calculate the deviations from the means
        double[] deviations1 = calculateDeviations(array1, mean1);
        double[] deviations2 = calculateDeviations(array2, mean2);

        // Calculate the covariance and variances
        double covariance = calculateCovariance(deviations1, deviations2);
        double variance1 = calculateVariance(deviations1);
        double variance2 = calculateVariance(deviations2);

        // Calculate the correlation
        return covariance / (Math.sqrt(variance1) * Math.sqrt(variance2));
    }

    /**
     * Calculates the mean of an array of data.
     * 
     * @param array The array of data.
     * @return The mean of the array.
     */
    private static double calculateMean(double[] array) {
        double sum = 0;
        for (double value : array) {
            sum += value;
        }
        return sum / array.length;
    }

    /**
     * Calculates the deviations from the mean for an array of data.
     * 
     * @param array The array of data.
     * @param mean The mean of the array.
     * @return The deviations from the mean.
     */
    private static double[] calculateDeviations(double[] array, double mean) {
        double[] deviations = new double[array.length];
        for (int i = 0; i < array.length; i++) {
            deviations[i] = array[i] - mean;
        }
        return deviations;
    }

    /**
     * Calculates the covariance between two arrays of data.
     * 
     * @param deviations1 The deviations from the mean for the first array.
     * @param deviations2 The deviations from the mean for the second array.
     * @return The covariance between the two arrays.
     */
    private static double calculateCovariance(double[] deviations1, double[] deviations2) {
        double covariance = 0;
        for (int i = 0; i < deviations1.length; i++) {
            covariance += deviations1[i] * deviations2[i];
        }
        return covariance;
    }

    /**
     * Calculates the variance of an array of data.
     * 
     * @param deviations The deviations from the mean.
     * @return The variance of the array.
     */
    private static double calculateVariance(double[] deviations) {
        double sum = 0;
        for (double deviation : deviations) {
            sum += deviation * deviation;
        }
        return sum / deviations.length;
    }

