Here's the Java code to calculate the minimum Euclidean distance from each point to any other observation:

```java
import java.util.*;

public class Main {
    public static void main(String[] args) {
        double[][] points = {{1, 2}, {3, 4}, {5, 6}};
        System.out.println(minimumEuclideanDistance(points));
    }

    public static double minimumEuclideanDistance(double[][] points) {
        int n = points.length;
        double[][] distances = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) {
                    continue;
                }
                double distance = euclideanDistance(points[i], points[j]);
                distances[i][j] = distance;
                distances[j][i] = distance;
            }
        }

        double minDistance = Double.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) {
                    continue;
                }
                minDistance = Math.min(minDistance, distances[i][j]);
            }
        }

        return minDistance;
    }

    public static double euclideanDistance(double[] point1, double[] point2) {
        double sum = 0;
        for (int i = 0; i < point1.length; i++) {
            sum += Math.pow(point1[i] - point2[i], 2);
        }
        return Math.sqrt(sum);
    }
}
```

