import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import org.xml.sax.SAXException;

import java.io.File;
import java.io.IOException;

public class Main {

    public static void main(String[] args) {
        // XML String
        String xmlString = "<root><person><name>John</name><age>30</age></person></root>";
        Document document = parseXmlString(xmlString);
        Element root = getRootElement(document);
        System.out.println(root.getNodeName());

        // XML File
        File xmlFile = new File("example.xml");
        Document documentFromFile = parseXmlFile(xmlFile);
        Element rootFromFile = getRootElement(documentFromFile);
        System.out.println(rootFromFile.getNodeName());

        // XML Document
        Document documentFromDocument = parseXmlDocument(new Document());
        Element rootFromDocument = getRootElement(documentFromDocument);
        System.out.println(rootFromDocument.getNodeName());
    }

    private static Document parseXmlString(String xmlString) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            return factory.newDocumentBuilder().parse(new java.io.ByteArrayInputStream(xmlString.getBytes()));
        } catch (ParserConfigurationException | SAXException | IOException e) {
            return null;
        }
    }

    private static Document parseXmlFile(File xmlFile) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            return factory.newDocumentBuilder().parse(xmlFile);
        } catch (ParserConfigurationException | SAXException | IOException e) {
            return null;
        }
    }

    private static Document parseXmlDocument(Document document) {
        return document;
    }

    private static Element getRootElement(Document document) {
        NodeList nodeList = document.getElementsByTagName("*");
        if (nodeList.getLength() > 0) {
            return (Element) nodeList.item(0);
        } else {
            return null;
        }
    }
}
```

