Here's an example of how to draw a focus rectangle on a graphics context using Java's 2D API.

```java
import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;

public class FocusRectangle extends JPanel {

    private int focusX, focusY;
    private int focusWidth, focusHeight;

    public FocusRectangle(int focusX, int focusY, int focusWidth, int focusHeight) {
        this.focusX = focusX;
        this.focusY = focusY;
        this.focusWidth = focusWidth;
        this.focusHeight = focusHeight;

        addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                if (isInsideFocusRect(e.getX(), e.getY())) {
                    focusX = e.getX();
                    focusY = e.getY();
                    repaint();
                }
            }
        });

        addMouseMotionListener(new MouseMotionAdapter() {
            @Override
            public void mouseDragged(MouseEvent e) {
                if (isInsideFocusRect(e.getX(), e.getY())) {
                    focusX = e.getX();
                    focusY = e.getY();
                    repaint();
                }
            }
        });
    }

    private boolean isInsideFocusRect(int x, int y) {
        return x >= focusX && x <= focusX + focusWidth && y >= focusY && y <= focusY + focusHeight;
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        Graphics2D g2d = (Graphics2D) g;
        g2d.setStroke(new BasicStroke(2));
        g2d.setColor(Color.RED);
        g2d.drawRect(focusX, focusY, focusWidth, focusHeight);
    }

    public static void main(String[] args) {
        JFrame frame = new JFrame("Focus Rectangle");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.add(new FocusRectangle(100, 100, 200, 200));
        frame.setSize(400, 400);
        frame.setVisible(true);
    }
}
```

