import java.util.stream.IntStream;
import java.util.function.Predicate;
import java.util.function.Consumer;

public class Main {
    public static void main(String[] args) {
        int quantity = 10; // Change this to get prime numbers for a different quantity
        IntStream numbers = IntStream.rangeClosed(2, quantity); // Start from 2, as 1 is not a prime number
        IntStream primeNumbers = numbers.filter(isPrime());
        primeNumbers.forEach(System.out::println);
    }

    private static Predicate<Integer> isPrime() {
        return n -> {
            if (n <= 1) return false;
            if (n == 2) return true;
            if (n % 2 == 0) return false;
            int sqrtN = (int) Math.sqrt(n);
            for (int i = 3; i <= sqrtN; i += 2) {
                if (n % i == 0) return false;
            }
            return true;
        };
    }
}
```

