```java
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

public class Main {

    public static void main(String[] args) throws Exception {
        // Create a sample DOM document
        Document document = javax.xml.parsers.DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();

        // Create a sample element
        Element element = document.createElement("div");
        document.appendChild(element);

        // Create another sample element
        Element childElement = document.createElement("p");
        element.appendChild(childElement);

        // Create another sample element
        Element grandChildElement = document.createElement("span");
        childElement.appendChild(grandChildElement);

        // Count the DOM element nodes before the supplied node, having the specified tag name
        int count = countNodesBefore(element, "div");
        System.out.println("Count of div nodes before the supplied node: " + count);
    }

    /**
     * Counts the DOM element nodes before the supplied node, having the specified tag name.
     * 
     * @param node The node to start counting from.
     * @param tagName The tag name to look for.
     * @return The count of nodes before the supplied node, having the specified tag name.
     */
    public static int countNodesBefore(Node node, String tagName) {
        int count = 0;
        Node currentNode = node.getParentNode();

        // Traverse up the DOM tree until we reach the root node
        while (currentNode != null) {
            // Check if the current node has the specified tag name
            if (currentNode.getNodeName().equals(tagName)) {
                // If it does, increment the count
                count++;
            }

            // Move up to the parent node
            currentNode = currentNode.getParentNode();
        }

        return count;
    }
}
```

