```java
import java.lang.Math;
import java.lang.Double;

public class Main {

    public static double calculateCorrelation(double[] array1, double[] array2) {
        double sum1 = 0, sum2 = 0, sum1Sq = 0, sum2Sq = 0, pSum = 0;
        int n = array1.length;

        for (int i = 0; i < n; i++) {
            double val1 = array1[i];
            double val2 = array2[i];

            if (!Double.isNaN(val1) && !Double.isNaN(val2)) {
                sum1 += val1;
                sum2 += val2;
                sum1Sq += val1 * val1;
                sum2Sq += val2 * val2;
                pSum += val1 * val2;
            }
        }

        double num = pSum - (sum1 * sum2 / n);
        double den = Math.sqrt((sum1Sq - sum1 * sum1 / n) * (sum2Sq - sum2 * sum2 / n));

        if (den == 0) {
            return 0; // or any other value that makes sense for your application
        }

        return num / den;
    }

    public static void main(String[] args) {
        double[] array1 = {1, 2, 3, 4, 5};
        double[] array2 = {2, 3, 5, 7, 11};

        double correlation = calculateCorrelation(array1, array2);
        System.out.println("Correlation: " + correlation);
    }
}
```

