    }

    public String resolveMessage(String code, MessageSourceResolvable resolvable) throws NoSuchMessageException {
        // Try to resolve the message
        String message = messageSource.getMessage(code, null, null);
        if (message == null) {
            // If no message was found, throw a NoSuchMessageException
