        }
        return message;
    }

    public String resolveMessage(String code, String defaultMessage) throws NoSuchMessageException {
        // Try to resolve the message
        String message = messageSource.getMessage(code, null, defaultMessage);
        if (message == null) {
            // If no message was found, throw a NoSuchMessageException
            throw new NoSuchMessageException("No message found for code '" + code + "'");
        }
        return message;
