        // Initialize the KeyPairGenerator with a key size of 2048 bits
        kpg.initialize(2048);

        // Generate a key pair
        KeyPair kp = kpg.generateKeyPair();
    }
}
```

### Storing the Key Pair in a Database

To store the key pair in a database, you'll need to convert the key pair into a format that can be stored in a database. One common format is PEM (Privacy-Enhanced Mail) format, which is a text-based format that can be easily stored in a database.

Here's an example of how to convert the key pair into PEM format:

```java
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.Base64;

public class Main {
    public static void main(String[] args) throws NoSuchAlgorithmException {
        // Create a KeyPairGenerator instance
        KeyPairGenerator kpg = KeyPairGenerator.getInstance("RSA");

        // Initialize the KeyPairGenerator with a key size of 2048 bits
        kpg.initialize(2048);

        // Generate a key pair
        KeyPair kp = kpg.generateKeyPair();

        // Get the public and private keys
        java.security.PublicKey publicKey = kp.getPublic();
        java.security.PrivateKey privateKey = kp.getPrivate();

        // Convert the public key into PEM format
        String publicKeyPem = getPublicKeyPem(publicKey);

        // Convert the private key into PEM format
        String privateKeyPem = getPrivateKeyPem(privateKey);

        // Store the public and private keys in the database
        // For example, using MySQL:
        // INSERT INTO public_keys (public_key) VALUES ('public_key_pem');
        // INSERT INTO private_keys (private_key) VALUES ('private_key_pem');
    }

    private static String getPublicKeyPem(java.security.PublicKey publicKey) {
        return "-----BEGIN PUBLIC KEY-----\n" +
                Base64.getEncoder().encodeToString(publicKey.getEncoded()) +
                "\n-----END PUBLIC KEY-----";
    }

    private static String getPrivateKeyPem(java.security.PrivateKey privateKey) {
        return "-----BEGIN PRIVATE KEY-----\n" +
                Base64.getEncoder().encodeToString(privateKey.getEncoded()) +
                "\n-----END PRIVATE KEY-----";
    }
}
```

Note that this is just a basic example, and you should consider using a more secure way to store the private key in the database, such as using a secure hash function to store the private key and then using the hash to retrieve the private key when needed.

