import java.io.DataOutput;
import java.io.IOException;

public class FixedStringToDataOutput implements DataOutput {

    @Override
    public void write(String s) throws IOException {
        // Write the length of the string
        writeLong(s.length());

        // Write each character of the string
        for (char c : s.toCharArray()) {
            writeByte(c);
        }
    }

    @Override
    public void write(long l) throws IOException {
        // Write the 8 bytes of the long value
        byte[] bytes = Long.toBytes(l);
        for (byte b : bytes) {
            writeByte(b);
        }
    }

    @Override
    public void write(byte[] b) throws IOException {
        // Write the length of the byte array
        writeLong(b.length);

        // Write each byte of the array
        for (byte bb : b) {
            writeByte(bb);
        }
    }

    @Override
    public void write(byte[] b, int off, int len) throws IOException {
        // Write the length of the byte array
        writeLong(len);

        // Write each byte of the array
        for (int i = 0; i < len; i++) {
            writeByte(b[off + i]);
        }
    }

    @Override
    public void writeBoolean(boolean b) throws IOException {
        // Write the 1 byte of the boolean value
        writeByte(b ? 1 : 0);
    }

    @Override
    public void writeByte(int b) throws IOException {
        // Write the 1 byte of the integer value
        this.write(b & 0xFF);
    }

    @Override
    public void writeShort(int s) throws IOException {
        // Write the 2 bytes of the short value
        this.write((s >> 8) & 0xFF);
        this.write(s & 0xFF);
    }

    @Override
    public void writeUShort(int s) throws IOException {
        // Write the 2 bytes of the unsigned short value
        this.writeShort(s & 0xFFFF);
    }

    @Override
    public void writeLong(long l) throws IOException {
        // Write the 8 bytes of the long value
        this.write((l >> 56) & 0xFF);
