        this.write((l >> 40) & 0xFF);
        this.write((l >> 32) & 0xFF);
        this.write((l >> 24) & 0xFF);
        this.write((l >> 16) & 0xFF);
        this.write((l >> 8) & 0xFF);
        this.write(l & 0xFF);
    }

    @Override
    public void writeUShort(long l) throws IOException {
        // Write the 2 bytes of the unsigned long value
        this.writeShort((int) (l & 0xFFFF));
    }

    @Override
    public void writeFloat(float f) throws IOException {
        // Write the 4 bytes of the float value
        this.writeFloat(f);
    }

    @Override
    public void writeDouble(double d) throws IOException {
        // Write the 8 bytes of the double value
        this.writeDouble(d);
    }

    @Override
    public void writeBytes(byte[] b) throws IOException {
