```java
import java.lang.reflect.Modifier;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.util.*;

public class Main {

    public static <T> List<Class<?>> getSubclassesAndInterfaces(Class<T> clazz) {
        List<Class<?>> subclassesAndInterfaces = new ArrayList<>();

        // Get all sub-classes
        for (Class<?> subClass : getSubclasses(clazz)) {
            if (!Modifier.isAbstract(subClass.getModifiers())) {
                subclassesAndInterfaces.add(subClass);
            }
        }

        // Get all implemented interfaces
        for (Class<?> interfaceClass : getInterfaces(clazz)) {
            if (!Modifier.isAbstract(interfaceClass.getModifiers())) {
                subclassesAndInterfaces.add(interfaceClass);
            }
        }

        return subclassesAndInterfaces;
    }

    private static <T> List<Class<?>> getSubclasses(Class<T> clazz) {
        List<Class<?>> subclasses = new ArrayList<>();

        for (Class<?> subClass : clazz.getClasses()) {
            if (subClass.isAssignableFrom(clazz) && !subClass.equals(clazz)) {
                subclasses.add(subClass);
            }
        }

        return subclasses;
    }

    private static <T> List<Class<?>> getInterfaces(Class<T> clazz) {
        List<Class<?>> interfaces = new ArrayList<>();

        for (Class<?> interfaceClass : clazz.getInterfaces()) {
            if (!Modifier.isAbstract(interfaceClass.getModifiers())) {
                interfaces.add(interfaceClass);
            }
        }

        return interfaces;
    }

    public static void main(String[] args) {
        // Example usage
        Class<?> clazz = String.class;
        List<Class<?>> subclassesAndInterfaces = getSubclassesAndInterfaces(clazz);

        for (Class<?> clazz1 : subclassesAndInterfaces) {
