```java
import java.lang.reflect.Array;
import java.util.Iterator;
import java.util.NoSuchElementException;

public class ObjectToIterable {
    public static <T> Iterable<T> convertToObjectIterable(Object obj) {
        Class<?> clazz = obj.getClass();
        if (clazz.isArray()) {
            int length = Array.getLength(obj);
            return new ArrayIterable<T>(clazz, length);
        } else {
            throw new UnsupportedOperationException("Not supported for non-array objects");
        }
    }

    private static class ArrayIterable<T> implements Iterable<T> {
        private final Class<?> clazz;
        private final int length;

        public ArrayIterable(Class<?> clazz, int length) {
            this.clazz = clazz;
            this.length = length;
        }

        @Override
        public Iterator<T> iterator() {
            return new ArrayIterator<T>(clazz, length);
        }
    }

    private static class ArrayIterator<T> implements Iterator<T> {
        private final Class<?> clazz;
        private final int length;
        private int index = 0;

        public ArrayIterator(Class<?> clazz, int length) {
            this.clazz = clazz;
            this.length = length;
        }

        @Override
        public boolean hasNext() {
            return index < length;
        }

        @Override
        public T next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            return (T) Array.get(obj, index++);
        }
    }
}
```

