public class ByteConverter {
    public static String convertBytesToHumanReadable(long bytes) {
        // Calculate the number of orders of magnitude
        double exponent = Math.log(bytes) / Math.log(1024);

        // Determine the human-readable format
        String format = getFormat(exponent);

        // Format the string
        return String.format(format, bytes);
    }

    private static String getFormat(double exponent) {
        // Determine the human-readable format based on the exponent
        if (exponent >= 0) {
            return String.format("%,d bytes", bytes);
