        } else if (exponent >= -3) {
            return String.format("%,d gigabytes", bytes / Math.pow(1024, 3));
        } else if (exponent >= -4) {
            return String.format("%,d terabytes", bytes / Math.pow(1024, 4));
        } else {
            return String.format("%,d petabytes", bytes / Math.pow(1024, 5));
        }
    }

    public static void main(String[] args) {
        System.out.println(convertBytesToHumanReadable(1024));
        System.out.println(convertBytesToHumanReadable(1024 * 1024));
        System.out.println(convertBytesToHumanReadable(1024 * 1024 * 1024));
    }
}
```

