```java
import javax.swing.*;
import java.awt.*;

public class DynamicExpansion extends JFrame {

    private JTable table;
    private JScrollPane scrollPane;

    public DynamicExpansion() {
        setLayout(new BorderLayout());

        // Create table and scroll pane
        table = new JTable();
        scrollPane = new JScrollPane(table);

        // Add action listener to table
        table.addActionListener(e -> {
            // Add row to table
            table.addRow(new Object[]{"Row " + (table.getRowCount() + 1), "Cell 1", "Cell 2"});
            // Revalidate and repaint scroll pane
            scrollPane.revalidate();
            scrollPane.repaint();
