            MidiEvent event = track.get(i);

            // Get the MIDI message from the event
            MidiMessage message = event.getMessage();

            // Get the status byte from the message
            int status = message.getStatus();

            // Check if the event is a note on event
            if (status == MidiMessage.NOTE_ON) {
                noteOnCount++;
            }
            // Check if the event is a note off event
            else if (status == MidiMessage.NOTE_OFF) {
                noteOffCount++;
            }
        }

        // Print the counts
        System.out.println("Note on events: " + noteOnCount);
        System.out.println("Note off events: " + noteOffCount);
    }
}
