```java
import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;
import java.net.SocketException;
import java.util.Scanner;

public class MulticastSender {
    public static void main(String[] args) throws SocketException {
        // Create a DatagramSocket
        DatagramSocket socket = new DatagramSocket();

        // Get the IP address of the multicast group
        InetAddress multicastGroup = InetAddress.getByName("224.1.1.1");

        // Create a byte array to hold the data to be sent
        byte[] data = "Hello, multicast!".getBytes();

        // Create a DatagramPacket
        DatagramPacket packet = new DatagramPacket(data, data.length, multicastGroup, 1234);

        // Create a thread to send the packet
        Thread senderThread = new Thread(() -> {
            try {
                // Send the packet
                socket.send(packet);

                // Sleep for a short period of time
                Thread.sleep(1000);
            } catch (Exception e) {
                System.out.println("Error sending packet: " + e.getMessage());
            }
        });

        // Start the sender thread
        senderThread.start();

        // Create a scanner to read input from the user
        Scanner scanner = new Scanner(System.in);

        // Continuously read input from the user and send it as packets
        while (true) {
            String input = scanner.nextLine();
            data = input.getBytes();
            packet = new DatagramPacket(data, data.length, multicastGroup, 1234);
            try {
                socket.send(packet);
                Thread.sleep(1000);
            } catch (Exception e) {
                System.out.println("Error sending packet: " + e.getMessage());
            }
        }
    }
}
```

This program creates a multicast sender that sends packets to the multicast group at IP address 224.1.1.1 on port 1234. It continuously reads input from the user and sends it as packets to the multicast group. The sender thread is used to send the initial packet, and the main thread is used to continuously read input from the user and send it as packets.

