```java
import javax.management.MBeanServer;
import javax.management.MBeanServerFactory;
import javax.management.MBeanServerNotificationListener;
import javax.management.MBeanServerNotificationListenerSupport;
import javax.management.ObjectName;
import javax.management.Notification;
import javax.management.NotificationListener;
import javax.management.RuntimeMBeanServerFactory;
import javax.management.RuntimeMBeanServerFactorySpi;
import java.lang.management.ManagementFactory;
import java.util.List;

public class MBeanUnregister {

    public static void unregisterMBean(String mbeanName) {
        // Get all MBeanServers
        List<MBeanServer> mbeanServers = MBeanServerFactory.findMBeanServer();

        // Iterate over each MBeanServer
        for (MBeanServer mbeanServer : mbeanServers) {
            try {
                // Create an ObjectName for the MBean to be unregistered
                ObjectName objectName = new ObjectName(mbeanName);

                // Register a notification listener to receive the unregistration notification
                MBeanServerNotificationListenerSupport.addNotificationListener(mbeanServer, new MBeanServerNotificationListener() {
                    @Override
                    public void notificationReceived(Notification notification) {
                        if (notification.getType().equals("mbean:unregister")) {
                            // Unregister the MBean
                            mbeanServer.unregisterObject(objectName);
                        }
                    }
                }, null, null);

                // Wait for the unregistration notification
                while (true) {
                    try {
                        Thread.sleep(1000);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            } catch (Exception e) {
                System.out.println("Error unregistering MBean: " + e.getMessage());
            } finally {
                // Remove the notification listener
                MBeanServerNotificationListenerSupport.removeNotificationListener(mbeanServer, new MBeanServerNotificationListener() {
                    @Override
                    public void notificationReceived(Notification notification) {
                    }
                }, null, null);
            }
        }
    }

    public static void main(String[] args) {
        // Get the MBeanServerFactory
        MBeanServerFactory factory = RuntimeMBeanServerFactorySpi.getPlatformMBeanServerFactory();

        // Unregister the MBean
        unregisterMBean("com.example.MBean");
    }
}
```

