import java.nio.ByteBuffer;
import java.nio.ByteOrder;

public class FloatToByteArray {

    public static void main(String[] args) {
        float floatValue = 10.5f;
        byte[] byteArray = new byte[4];

        // Write the float to the byte array
        writeFloatToByteArray(floatValue, byteArray, 0);

        // Print the byte array
        for (byte b : byteArray) {
            System.out.print(b + " ");
        }
    }

    public static void writeFloatToByteArray(float floatValue, byte[] byteArray, int offset) {
        ByteBuffer buffer = ByteBuffer.allocate(4);
        buffer.order(ByteOrder.BIG_ENDIAN); // Use big-endian byte order
