```java
public class FastqToPhredScores {
    public static byte[] fastqToPhredScores(String fastq) {
        // Split the FASTQ string into lines
        String[] lines = fastq.split("\n");

        // Initialize an empty byte array to store the phred scores
        byte[] phredScores = new byte[lines[0].length()];

        // Iterate over each line in the FASTQ string
        for (int i = 0; i < lines.length; i++) {
            // Check if the line is a sequence line
            if (i % 4 == 1) {
                // Extract the sequence
                String sequence = lines[i];

                // Iterate over each character in the sequence
                for (int j = 0; j < sequence.length(); j++) {
                    // Get the ASCII value of the character
                    int asciiValue = sequence.charAt(j);

                    // Calculate the phred score
                    int phredScore = asciiValue - 33;

                    // Store the phred score in the byte array
                    phredScores[j] = (byte) phredScore;
                }
            }
        }

        return phredScores;
    }

    public static void main(String[] args) {
        String fastq = "Sequence1\n" +
                "+\n" +
                "ATCG\n" +
                "+\n" +
                "Sequence2\n" +
                "+\n" +
                "ATCG\n" +
                "+";

        byte[] phredScores = fastqToPhredScores(fastq);

        // Print the phred scores
        for (byte score : phredScores) {
            System.out.print(score + " ");
        }
    }
}
```

