    public static void generatePerpendicularVectors(double x, double y, double z, double[] dest1, double[] dest2) {
        // Calculate the magnitude of the given vector
        double magnitude = Math.sqrt(x * x + y * y + z * z);

        // Check for division by zero
        if (magnitude == 0) {
            throw new ArithmeticException("Cannot generate perpendicular vectors from a zero vector");
        }

        // Generate the first perpendicular vector
        dest1[0] = y;
        dest1[1] = -x;
        dest1[2] = 0;

        // Generate the second perpendicular vector
