        // Create a custom object
        CustomObject customObject = new CustomObject("John Doe", 30);

        // Save the custom object to a file using ObjectOutputStream
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("custom_object.dat"))) {
            oos.writeObject(customObject);
            System.out.println("Custom object saved to file successfully.");
        }

        // Load the custom object from the file using ObjectInputStream
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream("custom_object.dat"))) {
