        return String.format("%.2f %s", scaledValue, unit);
    }

    private static String getUnit(double value) {
        if (value < 1024) {
            return "bytes";
        } else if (value < 1024 * 1024) {
            return "kilobytes";
        } else if (value < 1024 * 1024 * 1024) {
            return "megabytes";
        } else {
            return "gigabytes";
        }
    }

    public static void main(String[] args) {
        long bytes = 1024 * 1024 * 1024; // 1 GB
        System.out.println(convertByteSize(bytes)); // Output: 1.00 GB
    }
}
```

