Here's the Java code snippet that wraps up the nastiness of the Java XML transformation API for doing an identity transform, which allows an XML document to be converted to a string:

```java
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.dom.DOMSource;
import javax.xml.transform.stream.StreamResult;
import java.io.StringWriter;
import java.util.Properties;

public class XmlIdentityTransformer {

    public static String transformToIdentityXml(String xmlString) throws Exception {
        // Create a new TransformerFactory instance
        TransformerFactory factory = TransformerFactory.newInstance();

        // Create a new Transformer instance
        Transformer transformer = factory.newTransformer();

        // Create a StringWriter to hold the output
        StringWriter writer = new StringWriter();

        // Perform the identity transform
        transformer.transform(new DOMSource(xmlString), new StreamResult(writer));

        // Return the transformed XML as a string
        return writer.toString();
    }

    public static void main(String[] args) throws Exception {
        String xmlString = "<root><person><name>John</name><age>30</age></person></root>";
        String transformedXml = transformToIdentityXml(xmlString);
        System.out.println(transformedXml);
    }
}
```

