import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;

public class WindowStateTracker {
    public static void main(String[] args) {
        // Create a new window
        java.awt.Window window = java.awt.Toolkit.getDefaultToolkit().createWindow("Window State Tracker");

        // Add a window listener to track the window state
