            return "Maximized vertically";
        } else if (newState == java.awt.Window.ICONIFIED) {
            return "Iconified";
        } else if (newState == java.awt.Window.NORMAL) {
            return "Normal";
        } else {
            return "Unknown";
        }
    }
}
