```java
import java.lang.Math;

public class VectorCosineCalculator {

    public static double calculateCosine(double[] vector1, double[] vector2) {
        // Calculate the dot product of the two vectors
        double dotProduct = vector1[0] * vector2[0] + vector1[1] * vector2[1];

        // Calculate the magnitudes of the two vectors
        double magnitude1 = Math.sqrt(vector1[0] * vector1[0] + vector1[1] * vector1[1]);
        double magnitude2 = Math.sqrt(vector2[0] * vector2[0] + vector2[1] * vector2[1]);

        // Calculate the cosine of the angle between the two vectors
        double cosine = dotProduct / (magnitude1 * magnitude2);

        return cosine;
    }

    public static void main(String[] args) {
        double[] vector1 = {3, 4};
        double[] vector2 = {6, 8};

        double cosine = calculateCosine(vector1, vector2);
        System.out.println("Cosine of the angle between the two vectors: " + cosine);
    }
}
```

