        System.out.println("Bisector: " + bisector);
    }

    public static double getBisector(double p1, double p2, double p3) {
        // Calculate the vectors
        double v1 = p1 - p2;
        double v2 = p3 - p2;

        // Calculate the magnitude of the vectors
        double magnitude1 = Math.sqrt(v1 * v1);
        double magnitude2 = Math.sqrt(v2 * v2);

        // Check for division by zero
        if (magnitude1 == 0 || magnitude2 == 0) {
            throw new ArithmeticException("Cannot calculate bisector for zero vector");
        }

        // Calculate the bisector
        double bisector = (v1 + v2) / (2 * magnitude1 * magnitude2);

        return bisector;
    }
}
