```java
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Set<String> set = new HashSet<>(Arrays.asList("apple", "banana", "cherry", "date", "elderberry"));
        String barrierItem = "date";
        Set<String> copiedSet = copySet(set, barrierItem);
        System.out.println(copiedSet);
    }

    public static Set<String> copySet(Set<String> set, String barrierItem) {
        Set<String> copiedSet = new HashSet<>();
        for (String item : set) {
            if (!item.equals(barrierItem)) {
                copiedSet.add(item);
            }
        }
        return copiedSet;
    }
}
```

