    /**
     * Computes an appropriate foreground color (either white or black) for the given background color.
     * 
     * @param backgroundColor The background color.
     * @return The computed foreground color.
     */
    public static Color computeForegroundColor(Color backgroundColor) {
        float[] rgbComponents = backgroundColor.getRGBColorComponents(null);
        float red = rgbComponents[0];
        float green = rgbComponents[1];
        float blue = rgbComponents[2];

        // If the background color is white, the foreground color should be black.
        if (red == 1.0f && green == 1.0f && blue == 1.0f) {
            return Color.BLACK;
        }
        // If the background color is black, the foreground color should be white.
        else if (red == 0.0f && green == 0.0f && blue == 0.0f) {
            return Color.WHITE;
        }
        // If the background color is neither white nor black, the foreground color should be black.
        else {
            return Color.BLACK;
        }
    }
}
