```java
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import java.awt.image.DataBufferUShort;
import java.awt.image.DataBufferByte;
import java.awt.image.DataBufferFloat;
import java.awt.image.DataBufferDouble;
import java.awt.image.DataBufferChar;
import java.awt.image.DataBufferShort;
import java.awt.image.BufferedImage;

import javax.imageio.ImageIO;

public class ImageConverter {

    public static BufferedImage convertToTypeIntArgb(BufferedImage image) {
        int width = image.getWidth();
        int height = image.getHeight();

        // Create a new TYPE_INT_ARGB BufferedImage
        BufferedImage newImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);

        // Get the data from the original image
        int[] pixels = new int[width * height];
        image.getRGB(0, 0, width, height, pixels, 0, width);

        // Set the pixels in the new image
        for (int i = 0; i < pixels.length; i++) {
            int pixel = pixels[i];
            int alpha = (pixel >> 24) & 0xff;
            int red = (pixel >> 16) & 0xff;
            int green = (pixel >> 8)  & 0xff;
            int blue = pixel & 0xff;

            // Set the pixel in the new image
            newImage.setRGB(i, alpha, red, green, blue);
        }

        return newImage;
    }

