public class Main {
    public static void main(String[] args) {
        double normalizedValue = 0.5;
        long[] rgbaValues = convertToRainbow(normalizedValue);
        for (long rgbaValue : rgbaValues) {
            System.out.println(rgbaValue);
        }
    }

    public static long[] convertToRainbow(double normalizedValue) {
        int numValues = 256; // number of values in the rainbow
        long[] rgbaValues = new long[numValues];

        for (int i = 0; i < numValues; i++) {
            double value = (i / (double) (numValues - 1)) * 360; // calculate hue
            long red = (long) (Math.floor(value * 6) % 6 * 60 + 30); // calculate red
            long green = (long) (Math.floor((value % 6 + 2) / 6 * 60) + 30); // calculate green
            long blue = (long) (Math.floor((value % 6) * 60) + 30); // calculate blue
            long alpha = (long) (Math.floor(normalizedValue * 255)); // calculate alpha

            rgbaValues[i] = (red << 24) | (green << 16) | (blue << 8) | alpha;
        }

        return rgbaValues;
    }
}
```

