```java
import java.lang.Math;

public class EuclideanDistance {

    /**
     * Computes the Euclidean distance between two double value lists.
     * 
     * @param list1 the first list of double values
     * @param list2 the second list of double values
     * @return the Euclidean distance between the two lists
     */
    public static double computeEuclideanDistance(double[] list1, double[] list2) {
        if (list1.length != list2.length) {
            throw new IllegalArgumentException("Lists must be of the same length");
        }

        double sumOfSquares = 0;
        for (int i = 0; i < list1.length; i++) {
            sumOfSquares += Math.pow(list1[i] - list2[i], 2);
        }

        return Math.sqrt(sumOfSquares);
    }

    public static void main(String[] args) {
        double[] list1 = {1.0, 2.0, 3.0};
        double[] list2 = {4.0, 5.0, 6.0};

        double distance = computeEuclideanDistance(list1, list2);
        System.out.println("Euclidean distance: " + distance);
    }
}
```

