        // Get elements with a specific namespace and tag name
        NodeList elementsNS = document.getElementsByTagNameNS("http://example.com", "person");
        System.out.println("\nElements with namespace 'http://example.com' and tag name 'person':");
        for (int i = 0; i < elementsNS.getLength(); i++) {
            System.out.println(elementsNS.item(i).getNodeName());
        }
    }
}
