import java.net.URI;
import java.net.URLDecoder;
import java.util.HashMap;
import java.util.Map;

public class QueryStringToHashMap {
    public static Map<String, String> queryStringToHashMap(String queryString) throws Exception {
        URI uri = new URI(queryString);
        String query = uri.getQuery();
        Map<String, String> queryMap = new HashMap<>();
        if (query != null) {
            String[] pairs = query.split("&");
            for (String pair : pairs) {
                int idx = pair.indexOf("=");
                if (idx > 0) {
                    queryMap.put(URLDecoder.decode(pair.substring(0, idx), "UTF-8"), URLDecoder.decode(pair.substring(idx + 1), "UTF-8"));
                }
            }
        }
        return queryMap;
    }

    public static void main(String[] args) throws Exception {
        String queryString = "key1=value1&key2=value2";
        Map<String, String> queryMap = queryStringToHashMap(queryString);
        System.out.println(queryMap);
    }
}
```

This code uses the URI class to parse the query string and then splits it into key-value pairs. It then decodes the key and value using URLDecoder and adds them to the HashMap.

