Here's the Java code to normalize a vector:

```java
public class VectorNormalizer {

    /**
     * Normalizes a vector by dividing it by its length.
     * 
     * @param vector the vector to be normalized
     * @return the normalized vector
     */
    public static double[] normalize(double[] vector) {
        double length = calculateVectorLength(vector);
        if (length == 0) {
            throw new ArithmeticException("Cannot normalize a vector with zero length");
        }
        return divideVectorByLength(vector, length);
    }

    /**
     * Calculates the length of a vector using the Pythagorean theorem.
     * 
     * @param vector the vector to calculate the length of
     * @return the length of the vector
     */
    private static double calculateVectorLength(double[] vector) {
        double sumOfSquares = 0;
        for (double component : vector) {
            sumOfSquares += Math.pow(component, 2);
        }
        return Math.sqrt(sumOfSquares);
    }

    /**
     * Divides a vector by its length.
     * 
     * @param vector the vector to be divided
     * @param length the length of the vector
     * @return the vector divided by its length
     */
    private static double[] divideVectorByLength(double[] vector, double length) {
        double[] result = new double[vector.length];
        for (int i = 0; i < vector.length; i++) {
            result[i] = vector[i] / length;
        }
        return result;
    }

    public static void main(String[] args) {
        double[] vector = { 3, 4 };
        double[] normalizedVector = normalize(vector);
        System.out.println("Normalized Vector: " + java.util.Arrays.toString(normalizedVector));
    }
}
```

