            // Create a DocumentBuilderFactory instance
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

            // Create a DocumentBuilder instance
            DocumentBuilder builder = factory.newDocumentBuilder();

            // Create a Document instance
            Document document = builder.parse(new StringReader("<root><person><name>John</name></person></root>"));

            // Get the root element
            Element root = document.getDocumentElement();

            // Get all elements with the tag name "name"
            NodeList names = root.getElementsByTagName("name");

            // Check if the node exists
            if (names.getLength() > 0) {
                System.out.println("The node exists");
            } else {
                System.out.println("The node does not exist");
            }
        } catch (ParserConfigurationException | SAXException | IOException e) {
            e.printStackTrace();
        }
    }
}
```

