```java
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

public class Main {

    public static void main(String[] args) throws Exception {
        // Create a sample XML document
        Document doc = javax.xml.parsers.DocumentBuilderFactory.newInstance().newDocumentBuilder().parse("sample.xml");

        // Find the node with the name "target"
        Node node = findNode(doc.getDocumentElement(), "target");

        if (node != null) {
            System.out.println("Node found: " + node.getNodeName());
        } else {
            System.out.println("Node not found");
        }
    }

    /**
     * Recursively finds the XML node with the specified name.
     * 
     * @param node     the current node to search
     * @param name     the name of the node to find
     * @return the node with the specified name, or null if not found
     */
    public static Node findNode(Node node, String name) {
        if (node == null) {
            return null;
        }

        if (node.getNodeName().equals(name)) {
            return node;
        }

        NodeList children = node.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node child = children.item(i);
            if (child instanceof Element) {
                Node foundNode = findNode(child, name);
                if (foundNode != null) {
                    return foundNode;
                }
            }
        }

        return null;
    }
}
```

