    public static double interpolate(double startValue, double endValue, double position) {
        // Calculate the cosine of the position
        double cosine = Math.cos(position);

        // Calculate the interpolated value using the cosine
        double interpolatedValue = startValue + (endValue - startValue) * cosine;

        return interpolatedValue;
    }

    public static void main(String[] args) {
        // Example usage
        double startValue = 0.0;
        double endValue = 10.0;
        double position = 5.0;

        double interpolatedValue = interpolate(startValue, endValue, position);
        System.out.println("Interpolated value at position " + position + ": " + interpolatedValue);
    }
}
```

