public class DeadlockExample {
    private static final Lock lock1 = new ReentrantLock();
    private static final Lock lock2 = new ReentrantLock();

    public static void main(String[] args) {
        new Thread(new Runnable() {
            @Override
            public void run() {
                lock1.lock();
                try {
                    System.out.println(String.format("%s is locking lock1", Thread.currentThread().getName()));
                    lock2.lock();
                    try {
                        System.out.println(String.format("%s is locking lock2", Thread.currentThread().getName()));
                    } finally {
                        lock2.unlock();
                    }
                } finally {
                    lock1.unlock();
                }
            }
        }).start();

        new Thread(new Runnable() {
